1186:         public ExcuteResult TransferDispense1ToDispense2(bool isManual = false)
1187:         {
1188:             // 如果Dispense基板不是空闲状态
1189:             if (this.TransportProgram.DispenseSubSectionProgram.SubSectionState !=
1190:                 SubSectionStateEnum.HasMaterial)
1191:             {
1192:                 // 如果不满足条件
1193:                 return ExcuteResult.NoStart;
1194:             }
1195: 
1196:             // 如果不是手动调试模式
1197:             if (isManual == false)
1198:             {
1199:                 // 等点胶线程给信号
1200:                 bool rt = SignalPool.GetInstance().AllowDispense1TransferToDispense2Signal.Wait();
1201:                 if (rt == false)
1202:                 {
1203:                     // 如果点了停止 则退出
1204:                     return ExcuteResult.Abort;
1205:                 }
1206:             }
1207:             else
1208:             {
1209:                 if (ProductConfiguration.GetInstance().TransportUnitConfig.SubstrateProcessing == TransportUnitSystem.Model.SubstrateProcessingEnum.Divide)
1210:                 {
1211:                     if (!this.TransportProgram.DispenseSubSectionProgram.IsTuInDispense1)
1212:                     {
1213:                         return ExcuteResult.NoStart;
1214:                     }
1215:                 }
1216:                 else
1217:                 {
1218:                     return ExcuteResult.NoStart;
1219:                 }
1220:             }
1221: 
1222: 
1223:             LogHelper.Post(Level.Info, $"点胶流道收到信号可以传送到点胶2", LogCategory.Transport);
1224:             this.TransportProgram.DispenseSubSectionProgram.SubSectionTransferState =
1225:                     SubSectionStateTransferEnum.Transfering;
1226: 
1227:             // 轨道顶升气缸顶起
1228:             this.DispenseSubSectionController.UnClamp();
1229: 
1230:             // 点胶挡料1气缸降下 点胶挡料2气缸升起
1231:             this.DispenseSubSectionController.BlockCylinder1DownAndDelay(50);
1232:             this.DispenseSubSectionController.BlockCylinder2UpAndDelay(50);
1233: 
1234:             // 皮带转动
1235:             this.DispenseSubSectionController.MoveBeltWaitArrive();
1236: 
1237:             Thread.Sleep(200);
1238: 
1239:             // 轨道顶升气缸降下
1240:             this.DispenseSubSectionController.Clamp();
1241: 
1242:             // 状态改成有料
1243:             this.TransportProgram.DispenseSubSectionProgram.SubSectionState =
1244:                 SubSectionStateEnum.HasMaterial;
1245: 
1246:             this.TransportProgram.DispenseSubSectionProgram.SubSectionTransferState =
1247:                   SubSectionStateTransferEnum.Ready;
1248: 
1249:             // 将载具放在第二段
1250:             this.TransportProgram.DispenseSubSectionProgram.IsTuInDispense1 = false;
1251: 
1252:             // 坐标系发生改变
1253:             this.TransportProgram.DispenseSubSectionProgram.TransportUnit.System1MoveDistance();
1254: 
1255:             TransportDomain.GetInstance().TransportController.transportProgram.DispenseSubSectionProgram.TransportUnit
1256:                         .TransportUnitInfo.IsNeedPreDispense = true;
1257: 
1258:             return ExcuteResult.Success;
1259:         }

159:         public void InitializeTS()
160:         {
161:             // 如果在机器处于工作中，不能初始化流道
162:             if (Machine.GetInstance().IsWorking()
163:                 || Machine.GetInstance().IsPause())
164:             {
165:                 AKRSXtraMessageBox.Show("设备正在自动运行中，不能清空载具", "警告");
166: 
167:                 return;
168:             }
169: 
170:             DialogResult dr = AKRSXtraMessageBox.Show("清空轨道设备将不能记忆已经生产的信息，确认是否执行此操作", "提示", MessageBoxButtons.YesNo);
171:             switch (dr)
172:             {
173:                 case DialogResult.Yes:
174: 
175:                     if (MachineHardwareConfiguration.GetInstance().LoadConfiguration == LoadConfigurationEnum.LoaderBin)
176:                     {
177:                         // 上下料仓推杆缩回
178:                         this.LoaderBinController.MovePushRodHome();
179:                         this.UnLoaderBinController.MovePushRodHome();
180:                     }
181: 
182:                     if (MachineHardwareConfiguration.GetInstance().IsSystem1Configrated)
183:                     {
184:                         System1Domain.GetInstance().DispenseController.MoveToSafePos();
185:                     }
186: 
187:                     // 点胶和bond轴移动到安全位置
188:                     System2Domain.GetInstance().BondModuleController.MoveToSafePos();
189: 
190:                     this.DispenseSubSectionController.UnClamp();
191: 
192:                     // 点胶挡料气缸 降下
193:                     this.DispenseSubSectionController.BlockCylinder1DownAndDelay(50);
194:                     this.DispenseSubSectionController.BlockCylinder2DownAndDelay(50);
195: 
196: 
197:                     this.BondSubSectionController.UnClamp();
198: 
199:                     // bond 挡料气缸 降下
200:                     this.BondSubSectionController.BlockCylinderDownAndDelay(50);
201: 
202:                     // 清空记忆状态
203:                     this.transportProgram.LoadingSubSectionProgram.SubSectionState = SubSectionStateEnum.NoMaterial;
204:                     this.transportProgram.DispenseSubSectionProgram.SubSectionState = SubSectionStateEnum.NoMaterial;
205:                     this.transportProgram.BondSubSectionProgram.SubSectionState = SubSectionStateEnum.NoMaterial;
206:                     this.transportProgram.WaitingUnloadSubSectionProgram.SubSectionState = SubSectionStateEnum.NoMaterial;
207:                     this.transportProgram.UnloadingSubSectionProgram.SubSectionState = SubSectionStateEnum.NoMaterial;
208: 
209:                     // 清空载具对象
210:                     this.transportProgram.LoadingSubSectionProgram.TransportUnit = null;
211:                     this.transportProgram.DispenseSubSectionProgram.TransportUnit = null;
212:                     this.transportProgram.BondSubSectionProgram.TransportUnit = null;
213:                     this.transportProgram.WaitingUnloadSubSectionProgram.TransportUnit = null;
214:                     this.transportProgram.UnloadingSubSectionProgram.TransportUnit = null;
215:                     this.transportProgram.Save();
216: 
217:                     AKRSXtraMessageBox.Show("传输系统清空载具完成，请手动将所有载具拿走", "提示", MessageBoxButtons.OK, MessageBoxIcon.Information);
218: 
219:                     break;
220: 
221:                 case DialogResult.No:
222:                     break;
223:             }
224:         }

