84:         public void StartTask()
85:         {
86:             try
87:             {
88:                 if (!MachineHardwareConfiguration.GetInstance().IsTransportConfigured)
89:                 {
90:                     return;
91:                 }
92: 
93:                 TransportModule.GetInstance().Init();
94: 
95:                 if (MachineStateModel.GetInstance().MachineWorkMode == MachineWorkModeEnum.DryCycle)
96:                 {
97:                     this.transportTask.StartDryRun();
98:                 }
99:                 else
100:                 {
101:                     // 启动前检查
102:                     if (this.TransportController.CheckCarrierBeforeLoaderMove() == false)
103:                     {
104:                         Machine.GetInstance().Stop();
105:                         return;
106:                     }
107: 
108:                     if (MachineHardwareConfiguration.GetInstance().LoadConfiguration == LoadConfigurationEnum.Online)
109:                     {
110:                         this.TransportController.LoadingSubSectionController.SetLoadingTableNeedTabletSignal(false);
111:                     }
112: 
113: 
114:                     if (TransportDevicePara.GetInstance().IsReverseSearch)
115:                     {
116:                         // 2. 刷新流道的TransportUnit
117:                         TransportProgram.RefreshTransportUnit();
118:                     }
119: 
120:                     // 4. Check 流道看有没有料 并和记忆做匹配
121:                     this.TransportController.MapMaterial();
122: 
123:                     // 3、开启上下料
124:                     if (MachineHardwareConfiguration.GetInstance().LoadConfiguration == LoadConfigurationEnum.LoaderBin)
125:                     {
126:                         this.LoaderTask.Start();
127:                         this.UnloaderTask.Start();
128:                     }
129: 
130:                     // 产品位置记录显示
131:                     // FrmTransportSystemProductLocation.GetInstance().Show();
132:                     // 3. 流道线程开启
133:                     this.transportTask.Start();
134:                 }                
135:             }
136:             catch (Exception ex)
137:             {
138:                 LogHelper.Post(Level.Error, $"流道线程异常", ex, LogCategory.Transport);
139:                 AKRSXtraMessageBox.Show(ex.Message, "Transport task error", MessageBoxButtons.OK, MessageBoxIcon.Error);
140:             }
141:         }

2454:         public bool CheckCarrierBeforeLoaderMove()
2455:         {
2456:             // 出料、入料口是否有载具
2457:             bool hasMaterialInOutlet = false;
2458:             bool hasMaterialInFeedinglet = false;
2459: 
2460:         Retry:
2461:             // 出料口检测
2462:             hasMaterialInOutlet =
2463:                 this.UnloadingSubSectionController.HasMaterialInFeedingInlet();
2464: 
2465:             if (MachineHardwareConfiguration.GetInstance().LoadConfiguration == LoadConfigurationEnum.LoaderBin
2466:                 || MachineHardwareConfiguration.GetInstance().LoadConfiguration
2467:                 == LoadConfigurationEnum.OnlineWithAutoUnloader)
2468:             {
2469:                 if (hasMaterialInOutlet)
2470:                 {
2471:                     DialogResult dr = AKRSMessageBoxExt.Show(
2472:                         @"出料口有载具，下料仓不允许移动!请先移除出料口的载具！
2473:                               点击
2474:                               重试 : 重新检测
2475:                               终止: 停止工作",
2476:                         $"提示",
2477:                         new[] { "重试", "终止" },
2478:                         new[] { DialogResult.Retry, DialogResult.Abort },
2479:                         AlarmLevel.SecondLevel);
2480: 
2481:                     switch (dr)
2482:                     {
2483:                         case DialogResult.Retry:
2484:                             goto Retry;
2485: 
2486:                         case DialogResult.Abort:
2487:                             // 停止
2488:                             return false;
2489:                     }
2490:                 }
2491:             }
2492: 
2493:             // 入料口检测
2494:             hasMaterialInFeedinglet =
2495:                 this.DispenseSubSectionController.HasMaterialInFeedingInlet();
2496: 
2497:             if (MachineHardwareConfiguration.GetInstance().LoadConfiguration == LoadConfigurationEnum.LoaderBin
2498:                 || MachineHardwareConfiguration.GetInstance().LoadConfiguration
2499:                 == LoadConfigurationEnum.OnlineWithAutoLoader)
2500:             {
2501:                 if (hasMaterialInFeedinglet)
2502:                 {
2503:                     DialogResult dr = AKRSMessageBoxExt.Show(
2504:                         @"入料口有载具，上料仓不允许移动!请先移除入料口的载具！
2505:                               点击
2506:                               重试 : 重新检测
